import "server-only";
import type { User } from "./users";
import { getResend } from "./resend";
import { WelcomeEmail } from "@/emails/welcome";
import { PasswordResetEmail } from "@/emails/password-reset";

const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";

// Resend resolves to { error } instead of throwing on a refused message. Email must never
// break the request that triggered it, so failures are logged and swallowed.
async function send(to: string, subject: string, react: React.ReactElement, text: string) {
  try {
    const from = process.env.RESEND_FROM_EMAIL;
    if (!from) throw new Error("RESEND_FROM_EMAIL is not set");
    const { error } = await getResend().emails.send({ from, to, subject, react, text });
    if (error) console.error(`Email "${subject}" failed: ${error.name}: ${error.message}`);
  } catch (e) {
    console.error(`Email "${subject}" failed`, e);
  }
}

export function sendWelcomeEmail(user: User) {
  const url = appUrl();
  return send(
    user.email,
    "Welcome to Notely",
    WelcomeEmail({ name: user.name, appUrl: url }),
    `Welcome to Notely, ${user.name}! Open Notely: ${url}`,
  );
}

export function sendPasswordResetEmail(user: User, token: string) {
  const actionUrl = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  return send(
    user.email,
    "Reset your password",
    PasswordResetEmail({ name: user.name, actionUrl }),
    `Hi ${user.name}, reset your Notely password (link expires in 1 hour): ${actionUrl}`,
  );
}
EOF
cat > .env.example <<'EOF'
# Resend (https://resend.com/api-keys). Copy to .env.local and fill in.
RESEND_API_KEY=re_placeholder
# Must be on a domain verified in Resend, or onboarding@resend.dev while testing.
RESEND_FROM_EMAIL=Notely <onboarding@resend.dev>
# Public base URL used in email links.
APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
ls node_modules/server-only >/dev/null 2>&1 && echo has-server-only

